    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                positions.setdefault(grid[r][c], set()).add((r, c))

    for color, cells in positions.items():
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in list(cells):
                # A consecutive diagonal pair identifies a line direction.
                if (r + dr, c + dc) not in cells:
                    continue
                # Extend from both ends of this diagonal run.
                for sr, sc in ((r, c), (r + dr, c + dc)):
                    rr, cc = sr, sc
                    step_r, step_c = (-dr, -dc) if (sr, sc) == (r, c) else (dr, dc)
                    while 0 <= rr + step_r < h and 0 <= cc + step_c < w:
                        rr += step_r
                        cc += step_c
                        if out[rr][cc] != bg:
                            break
                        out[rr][cc] = color
    return out
